#!/bin/bash
# Run test/shim_test.c (init, route, matrix, locate) against the built Linux library.
# Test data: the public Idaho tile extract (same one the iOS plan uses), checked by SHA256; a config generated by Valhalla's own
# valhalla_build_config with the paths to files we do not ship removed (admin, timezone, landmarks, transit, traffic).
# Usage: test-linux.sh <package-dir (lib/, include/)> <valhalla-src-dir> <work-dir>
set -euo pipefail
[[ $# == 3 ]] || { echo "usage: $0 <package-dir> <valhalla-src> <work-dir>" >&2; exit 2; }
pkg=$(cd "$1" && pwd); src=$(cd "$2" && pwd); mkdir -p "$3"; work=$(cd "$3" && pwd)
here=$(cd "$(dirname "$0")/.." && pwd)
url=https://github.com/zvx-echo6/cache-packs/releases/download/idaho-2026-10-25/valhalla-idaho-2026-10-25.tar.part00
sha=41a0f5c548f904c8718cd53c90e662dc565cdf6a1a55546416d0537d959daf48
tiles=$work/tiles.tar
if ! { [[ -f "$tiles" ]] && echo "$sha  $tiles" | sha256sum -c --quiet -; }; then
  curl -fL --retry 5 --retry-delay 5 -o "$tiles" "$url"
  echo "$sha  $tiles" | sha256sum -c -
fi
python3 "$src/scripts/valhalla_build_config" --mjolnir-tile-extract "$tiles" --mjolnir-tile-dir "$work/tiles" > "$work/config.full.json"
python3 - "$work" <<'PY'
import json, sys
w = sys.argv[1]
c = json.load(open(w + "/config.full.json"))
for k in ("admin", "landmarks", "timezone", "transit_dir", "transit_feeds_dir", "traffic_extract"):
    c["mjolnir"].pop(k, None)
json.dump(c, open(w + "/config.json", "w"))
open(w + "/route.json", "w").write(json.dumps({"locations": [{"lat": 42.536, "lon": -113.792}, {"lat": 43.615, "lon": -116.202}], "costing": "auto", "units": "kilometers"}))
open(w + "/matrix.json", "w").write(json.dumps({"sources": [{"lat": 43.615, "lon": -116.202}, {"lat": 43.5407, "lon": -116.5635}], "targets": [{"lat": 43.6121, "lon": -116.3915}, {"lat": 43.6629, "lon": -116.6874}], "costing": "auto"}))
open(w + "/locate.json", "w").write(json.dumps({"locations": [{"lat": 43.615, "lon": -116.202}], "costing": "auto", "verbose": True}))
PY
gcc -O1 -Wall -I "$pkg/include" "$here/test/shim_test.c" -L "$pkg/lib" -lvalhalla_shim -Wl,-rpath,"$pkg/lib" -o "$work/valhalla_shim_test"
for a in route matrix locate; do
  echo "== $a"
  "$work/valhalla_shim_test" "$work/config.json" "$a" "$work/$a.json" 2 -q -o "$work/$a.out.json"
done
python3 - "$work" <<'PY'
import json, sys
w = sys.argv[1]
r = json.load(open(w + "/route.out.json"))["trip"]
km = r["summary"]["length"]; mans = len(r["legs"][0]["maneuvers"])
print("route km", km, "maneuvers", mans)
assert 200 <= km <= 350 and mans > 0
m = json.load(open(w + "/matrix.out.json"))["sources_to_targets"]
d = [x["distance"] for row in m for x in row]
print("matrix distances", d)
assert len(d) == 4 and all(v is not None and v >= 0 for v in d)
l = json.load(open(w + "/locate.out.json"))
print("locate edges", len(l[0].get("edges", [])))
assert l and len(l[0].get("edges", [])) > 0
print("SHIM TEST OK")
PY
